interface Discount {
    int apply(int cents);
}
class TenPercent implements Discount {
    public int apply(int cents) { return cents - cents / 10; }
}
class MinusFive implements Discount {
    public int apply(int cents) { return cents - 500; }
}

int total = 10000;
for (Discount d : List.of(new TenPercent(), new MinusFive(), new TenPercent())) {
    total = d.apply(total);
}
System.out.println(total);

