class Coin {
    final int cents;
    Coin(int cents) { this.cents = cents; }

    public boolean equals(Coin other) {
        return cents == other.cents;
    }
}

Coin a = new Coin(5);
Object b = new Coin(5);
System.out.println(a.equals(new Coin(5)) + " " + a.equals(b));

